 void reset(uint8_t flags,uint8_t mode){prep(0x2f80,flags);byte(0xcd0e,mode);kstation::NativeMidiSysExReset t;unsigned n=0;while(!t.task().complete()){check(++n<10,"reset hang");check(t.step(*b),"reset phase");a->step();equal();check(!std::memcmp(a->memory+0xcc06,b->memory+0xcc06,8),"reset state mismatch");check(a->memory[0xcd0e]==b->memory[0xcd0e],"reset mode mismatch");++phases;}++graphs;}
 void prefix(uint8_t flags,uint8_t part,uint8_t rate){using X=kstation::NativeVoiceGlobal::External;prep(0x79a4,flags);byte(0xd028,part);wide(0xbfaa+16u*part,0xc600);byte(0xc655,rate);for(unsigned field=0x51;field<=0x63;++field)byte(0xc600+field,uint8_t(rate^field));byte(0xc655,rate);byte(0xc671,uint8_t(rate^0x5f));byte(0xc670,uint8_t(rate^0xa0));byte(0xc692,uint8_t(rate^0x40));word(0xbf98,1000);word(0xbf9c,uint16_t(rate*257));auto mode=uint8_t(rate^0x5f);wide(0xc59a+uint8_t(uint8_t(mode-1)*4),rnd());byte(0xc673,uint8_t(rate&0x7f));byte(0xc674,uint8_t(rate&0x7f));byte(0xc691,uint8_t(rate%8));byte(0xc66d,rate);byte(0xc667,uint8_t(rate%3));byte(0xc666,rate);byte(0xc66a,rate);byte(0xc677,uint8_t(rate%3));byte(0xc676,rate);byte(0xc678,rate);byte(0xc675,rate);byte(0xc67b,rate);byte(0xc6c6,rate);byte(0xc6c5,rate);byte(0xc6c4,uint8_t(rate%2));byte(0xc659,uint8_t(rate%3));byte(0xc65a,rate);byte(0xc65b,uint8_t(rate^0x5a));byte(0xd029,uint8_t(rate%2));byte(0xd022,8);for(unsigned vi=0;vi<8;++vi){wide(0xd030+18*vi,0xc600);byte(0xd034+18*vi,0);word(0xd038+18*vi,vi&1?0x8001:0);}kstation::NativeVoiceGlobal owner;check(owner.admitPrefix(*b,0x7000),"global prefix admit");unsigned n=0,continuations=0;while(uint32_t(a->getPC())!=0x7000||owner.active()){check(++n<3000,"global prefix hang");if(owner.step(*b)){a->step();equal();++phases;continue;}equal();if(uint32_t(a->getPC())==0x7000&&!owner.active())break;auto ch=owner.external();auto sp=a->getSP();uint32_t ret=0;for(unsigned i=0;i<4;++i)ret=(ret<<8)|a->memory[(sp+i)&0xffffff];ret&=0xffffff;if(ch==X::Send){uint32_t semantic=0;if(owner.laneValue(semantic))check(uint32_t(a->reg32(1))==semantic,"global semantic lane value");}if(!ret)std::fprintf(stderr,"prefix unserved pc=%x external=%u active=%d\n",unsigned(a->getPC()),unsigned(ch),owner.active());check(ret&&ch!=X::None,"global prefix child");kstation::NativeVoiceAllocation allocation;kstation::NativeVoiceUpdate update;kstation::NativeDspTransfer dsp;kstation::NativeMidiEvents events;unsigned k=0;while(uint32_t(a->getPC())!=ret||allocation.active()||update.active()||dsp.active()||events.active()){check(++k<1000,"global allocation hang");bool ok=events.step(*b);if(!ok)ok=update.step(*b);if(!ok)ok=allocation.step(*b);if(!ok)ok=dsp.step(*b);if(ok){a->step();equal();++phases;continue;}equal();check(uint32_t(a->getPC())==ret&&!allocation.active()&&!update.active()&&!dsp.active(),"global allocation missing");}++children;}check(continuations==0,"global continuation count");++graphs;}
 void ownerRelease(uint8_t flags,uint8_t start,uint8_t mask){using X=kstation::NativeVoiceGlobal::External;prep(0x7762,flags);a->reg8(0)=b->reg8(0)=int8_t(start);byte(0xd022,8);byte(0xd028,0);for(unsigned i=0;i<8;++i){auto v=0xd030+18*i;wide(v,0xc600);byte(v+4,0);word(v+8,mask&(1u<<i)?0x8001:0);}kstation::NativeVoiceGlobal owner;unsigned n=0;while(uint32_t(a->getPC())!=0x7000||owner.active()){check(++n<10000,"release owner hang");if(owner.step(*b)){a->step();equal();++phases;continue;}equal();if(uint32_t(a->getPC())==0x7000&&!owner.active())break;auto ch=owner.external();uint32_t ret=ch==X::VoiceAddress?0x7774:ch==X::Bus?0x77a0:ch==X::Send?0x77ac:ch==X::Release?0x77b0:0;check(ret,"release owner child");kstation::NativeVoiceAllocation allocation;kstation::NativeVoiceUpdate update;kstation::NativeDspTransfer dsp;kstation::NativeMidiEvents events;unsigned k=0;while(uint32_t(a->getPC())!=ret||allocation.active()||update.active()||dsp.active()||events.active()){check(++k<5000,"release owner child hang");bool ok=events.step(*b);if(!ok)ok=update.step(*b);if(!ok)ok=allocation.step(*b);if(!ok)ok=dsp.step(*b);check(ok,"release owner child missing");a->step();equal();++phases;}++children;}++graphs;}
 void releaseAbove(uint8_t flags,uint8_t start,uint8_t mask){using T=kstation::VoiceReleaseAboveTask;prep(0x7762,flags);a->reg8(0)=b->reg8(0)=int8_t(start);byte(0xd022,8);byte(0xd028,0);for(unsigned i=0;i<256;++i){auto v=0xd030+18*i;wide(v,0xc600);byte(v+4,0);word(v+8,(i<8&&(mask&(1u<<i)))?0x8001:0);}kstation::NativeVoiceReleaseAbove t(start);unsigned n=0;while(!t.task().complete()){check(++n<10000,"release above hang");if(t.task().awaitingChild()){auto ch=t.task().child();uint32_t ret=ch==T::Child::Address?0x7774:ch==T::Child::Bus?0x77a0:ch==T::Child::Send?0x77ac:0x77b0;kstation::NativeVoiceAllocation allocation;kstation::NativeVoiceUpdate update;kstation::NativeDspTransfer dsp;kstation::NativeMidiEvents events;unsigned k=0;while(uint32_t(a->getPC())!=ret||allocation.active()||update.active()||dsp.active()||events.active()){check(++k<5000,"release child hang");bool ok=events.step(*b);if(!ok)ok=update.step(*b);if(!ok)ok=allocation.step(*b);if(!ok)ok=dsp.step(*b);check(ok,"release child missing native");a->step();equal();++phases;}check(t.resumeChild(*b),"release above resume");++children;continue;}check(t.step(*b),"release above phase");a->step();equal();++phases;}check(uint32_t(a->getPC())==0x7000,"release above return");++graphs;}
 void rate(uint8_t flags,uint8_t index,uint32_t value){prep(0x342a,flags);a->reg8(8)=b->reg8(8)=int8_t(index);uint32_t at=0xabf4+uint8_t(index*4);wide(at,value);kstation::NativeArpRateSelect t(index);unsigned n=0;while(!t.task().complete()){check(++n<20,"rate hang");check(t.step(*b),"rate phase");a->step();equal();check(!std::memcmp(a->memory+0xcd30,b->memory+0xcd30,4),"rate output");++phases;}check(t.task().value()==value,"rate lookup");++graphs;}void root(uint8_t flags,uint16_t value){prep(0x80b4,flags);a->reg16(8)=b->reg16(8)=int16_t(value);kstation::NativeVoiceIntegerRoot t(value);unsigned n=0;while(!t.task().complete()){check(++n<100,"root hang");check(t.step(*b),"root phase");a->step();equal();++phases;}auto v=t.task().result();check(unsigned(v)*v<=value&&(v==255||unsigned(v+1)*(v+1)>value),"root result");++graphs;}
