int main(int argc,char**argv){try{if(argc<2)return 77;std::ifstream in(argv[1],std::ios::binary);std::vector<uint8_t>rom{std::istreambuf_iterator<char>(in),{}};check(rom.size()==49728,"ROM size");F f(rom);for(unsigned flags=0;flags<256;++flags)for(uint8_t rate:{uint8_t(0),uint8_t(1),uint8_t(95),uint8_t(127),uint8_t(255)})for(uint8_t part:{uint8_t(0),uint8_t(1),uint8_t(3),uint8_t(15)})f.prefix(uint8_t(flags),part,rate);for(unsigned rate=0;rate<256;++rate)for(uint8_t flags:{uint8_t(0),uint8_t(0x80),uint8_t(0xff)})f.prefix(flags,0,uint8_t(rate));for(unsigned flags=0;flags<256;++flags)for(uint8_t start:{uint8_t(0),uint8_t(1),uint8_t(7),uint8_t(8)})for(uint8_t mask:{uint8_t(0),uint8_t(0xff)})f.ownerRelease(uint8_t(flags),start,mask);for(unsigned flags=0;flags<256;++flags)for(uint8_t start:{uint8_t(0),uint8_t(1),uint8_t(7),uint8_t(8)})for(uint8_t mask:{uint8_t(0),uint8_t(1),uint8_t(0x80),uint8_t(0xff)})f.releaseAbove(uint8_t(flags),start,mask);for(uint8_t flags:{uint8_t(0),uint8_t(0x80),uint8_t(0xff)})for(uint8_t start:{uint8_t(9),uint8_t(255)})f.releaseAbove(flags,start,0);for(unsigned flags=0;flags<256;++flags)for(unsigned index=0;index<256;++index)f.rate(uint8_t(flags),uint8_t(index),rnd());for(unsigned value=0;value<65536;++value)for(uint8_t flags:{uint8_t(0),uint8_t(0x80),uint8_t(0xff)})f.root(flags,uint16_t(value));for(unsigned flags=0;flags<256;++flags)for(uint16_t value:{uint16_t(0),uint16_t(1),uint16_t(2),uint16_t(0xff),uint16_t(0x100),uint16_t(0x7fff),uint16_t(0xffff)})f.root(uint8_t(flags),value);std::printf("{\"passed\":true,\"graphs\":%llu,\"native_phases\":%llu,\"ordered_bus_events\":%llu,\"native_children\":%llu}\n",(unsigned long long)f.graphs,(unsigned long long)f.phases,(unsigned long long)f.events,(unsigned long long)f.children);return 0;}catch(const std::exception&e){std::fprintf(stderr,"FAIL: %s\n",e.what());return 1;}}
